let state = loadState();
let searchFilters = { query: '', location: '', category: '' };
let applicantFilter = 'all';
let storageWarningShown = false;

function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (saved && saved.users && saved.jobs && saved.applications) return { ...structuredClone(seedData), ...saved };
  } catch (error) { console.warn('Starting with fresh demo data.', error); }
  return structuredClone(seedData);
}

function persist() {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch (error) {
    if (!storageWarningShown) {
      storageWarningShown = true;
      toast('Browser storage is unavailable. Changes will last only while this page stays open.');
    }
  }
}
function personForRole(role) { const id = ({ admin: 'u-admin', employer: 'u-employer', seeker: 'u-seeker' })[role]; return state.users.find(user => user.id === id) || structuredClone(seedData.users.find(user => user.id === id)); }
function currentUser() { return personForRole(state.role); }
function initials(name) { return name.split(/\s+/).map(part => part[0]).join('').slice(0, 2).toUpperCase(); }
function escapeHtml(value = '') { return String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char])); }
function setActivity(text, icon = '✓') { state.activity.unshift({ text, icon, time: 'Just now' }); state.activity = state.activity.slice(0, 12); }
function toast(message, success = true) {
  const node = document.createElement('div'); node.className = `toast${success ? ' success' : ''}`; node.textContent = message;
  document.getElementById('toast-region').appendChild(node); setTimeout(() => node.remove(), 3200);
}
function fmtRole(role) { return ({ seeker: 'Job seeker', employer: 'Employer', admin: 'Administrator' })[role] || role; }
function jobById(id) { return state.jobs.find(job => job.id === id); }
function personById(id) { return state.users.find(user => user.id === id) || { name: 'Former member', email: '—', title: 'Member' }; }
function appById(id) { return state.applications.find(app => app.id === id); }
function logo(job, small = false) { return `<span class="company-logo" style="background:${escapeHtml(job.color)};color:${escapeHtml(job.logoColor)};${small ? 'width:29px;height:29px;border-radius:8px;font-size:10px' : ''}">${escapeHtml(job.initials || job.company?.[0] || '?')}</span>`; }
function statusPill(status) { const labels = { approved: 'Live', pending: 'Pending review', rejected: 'Needs changes', closed: 'Closed', review: 'In review', shortlisted: 'Shortlisted', interview: 'Interview', offer: 'Offer', hired: 'Hired', withdrawn: 'Withdrawn' }; return `<span class="status-pill ${escapeHtml(status)}">${labels[status] || escapeHtml(status)}</span>`; }

function render() {
  const nav = navItems();
  document.getElementById('side-nav').innerHTML = nav.map(item => `<button class="nav-item ${state.tab === item.label ? 'active' : ''}" data-action="tab" data-tab="${escapeHtml(item.label)}"><span class="nav-icon">${item.icon}</span>${escapeHtml(item.label)}${item.count ? `<span class="nav-count">${item.count}</span>` : ''}</button>`).join('');
  const user = currentUser();
  document.getElementById('sidebar-profile').innerHTML = `<span class="avatar">${initials(user.name)}</span><div class="profile-copy"><strong>${escapeHtml(user.name)}</strong><span>${escapeHtml(user.title)}</span></div><button class="icon-button" data-action="profile" aria-label="Edit profile">···</button>`;
  document.getElementById('top-avatar').textContent = initials(user.name);
  document.getElementById('role-switcher').value = state.role;
  document.getElementById('crumb-current').textContent = state.tab;
  const content = document.getElementById('page-content');
  if (state.role === 'seeker') content.innerHTML = renderSeeker();
  if (state.role === 'employer') content.innerHTML = renderEmployer();
  if (state.role === 'admin') content.innerHTML = renderAdmin();
  persist();
}

function navItems() {
  if (state.role === 'seeker') {
    const tabs = ['Discover jobs', 'My applications', 'Saved jobs', 'Messages', 'My profile'];
    return tabs.map((label, i) => ({ label, icon: ['⌕', '▤', '☆', '✉', '◉'][i], count: i === 1 ? state.applications.filter(app => app.seekerId === currentUser().id && !['rejected', 'withdrawn'].includes(app.status)).length : i === 3 ? userMessagesCount() : 0 }));
  }
  if (state.role === 'employer') return ['Overview', 'Jobs & applicants', 'Messages', 'Insights', 'Company profile'].map((label, i) => ({ label, icon: ['◫', '▣', '✉', '▥', '◉'][i], count: i === 1 ? employerApplications().length : i === 2 ? userMessagesCount() : 0 }));
  return ['Overview', 'Job approvals', 'User management', 'System settings', 'Activity log'].map((label, i) => ({ label, icon: ['◫', '✓', '♙', '⚙', '◷'][i], count: i === 1 ? state.jobs.filter(job => job.status === 'pending').length : 0 }));
}

function pageHeading(eyebrow, title, description, actions = '') { return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${actions ? `<div class="heading-actions">${actions}</div>` : ''}</div>`; }
function statCard(label, value, note, icon, tint = '') { return `<div class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon ${tint}">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`; }
function tabStrip(tabs, active, action = 'tab') { return `<div class="tabs">${tabs.map(tab => `<button class="tab-button ${tab === active ? 'active' : ''}" data-action="${action}" data-tab="${escapeHtml(tab)}">${escapeHtml(tab)}</button>`).join('')}</div>`; }

function renderSeeker() {
  if (state.tab === 'My applications') return seekerApplicationsPage();
  if (state.tab === 'Saved jobs') return seekerSavedPage();
  if (state.tab === 'Messages') return messagesPage('YOUR CONVERSATIONS', 'Messages', 'A good conversation can be the start of something great.');
  if (state.tab === 'My profile') return seekerProfilePage();
  return seekerDiscoverPage();
}

function seekerDiscoverPage() {
  const myApps = state.applications.filter(app => app.seekerId === currentUser().id);
  const activeApps = myApps.filter(app => !['rejected', 'withdrawn'].includes(app.status)).length;
  const appliedIds = new Set(myApps.map(app => app.jobId));
  const publicJobs = state.jobs.filter(job => job.status === 'approved');
  const filtered = publicJobs.filter(job => {
    const text = `${job.title} ${job.company} ${job.description} ${job.tags.join(' ')}`.toLowerCase();
    return (!searchFilters.query || text.includes(searchFilters.query.toLowerCase())) && (!searchFilters.location || job.location.toLowerCase().includes(searchFilters.location.toLowerCase())) && (!searchFilters.category || job.category === searchFilters.category);
  });
  const recommended = publicJobs.find(job => !appliedIds.has(job.id) && job.category === 'Design') || publicJobs[0];
  return `${pageHeading('YOUR NEXT CHAPTER', `Good morning, ${escapeHtml(currentUser().name.split(' ')[0])} <span aria-hidden="true">✦</span>`, 'A fresh week brings fresh possibilities. Here are a few places to start.', `<button class="btn btn-secondary" data-action="profile"><span class="button-icon">＋</span> Complete your profile</button>`)}
    <div class="stat-grid">${statCard('Applications in progress', activeApps, '<span class="positive">Keep going</span> · every step counts', '↗', 'green')}${statCard('Interviews', myApps.filter(app => app.status === 'interview').length, 'You’re making great progress', '◷', 'blue')}${statCard('Saved for later', state.savedJobIds.length, 'Roles you want to revisit', '☆', 'amber')}${statCard('Profile strength', '78%', 'Add a few details to stand out', '◉', 'green')}</div>
    <div class="search-panel"><form class="search-form" id="job-search-form"><div class="field-wrap"><span class="field-icon">⌕</span><input class="field" name="query" placeholder="Job title, skill, or company" value="${escapeHtml(searchFilters.query)}" /></div><div class="field-wrap"><span class="field-icon">⌖</span><input class="field" name="location" placeholder="City or remote" value="${escapeHtml(searchFilters.location)}" /></div><select class="select-field" name="category"><option value="">All categories</option>${['Design', 'Engineering', 'Marketing', 'People', 'Customer Success'].map(cat => `<option ${searchFilters.category === cat ? 'selected' : ''}>${cat}</option>`).join('')}</select><button class="btn btn-primary" type="submit"><span class="button-icon">⌕</span> Find a role</button></form></div>
    <div class="two-column"><div><div class="job-toolbar"><div><h2>${searchFilters.query || searchFilters.location || searchFilters.category ? 'Search results' : 'Roles picked for you'}</h2><span class="result-count">${filtered.length} opportunities to explore</span></div><button class="text-link" data-action="clear-search">Clear filters</button></div>${filtered.length ? `<div class="job-grid">${filtered.map(job => jobCard(job, appliedIds.has(job.id))).join('')}</div>` : emptyState('No roles found yet', 'Try a different title, location, or category.')}</div><div class="side-stack"><div class="panel profile-card"><span class="avatar">${initials(currentUser().name)}</span><h3>${escapeHtml(currentUser().name)}</h3><p>${escapeHtml(currentUser().title)} · Bengaluru</p><div class="profile-meter"><span></span></div><div class="meter-label"><span>Profile completeness</span><b>78%</b></div><button class="btn btn-secondary btn-small" style="margin-top:14px;width:100%" data-action="profile">Make your profile shine</button></div>${recommended ? `<div class="panel recommend-card"><div class="panel-body"><div class="eyebrow">A GOOD MATCH FOR YOU</div><h3>${escapeHtml(recommended.title)}</h3><p>${escapeHtml(recommended.company)} · ${escapeHtml(recommended.location)}<br>${escapeHtml(recommended.salary)}</p><button class="btn btn-small" data-action="view-job" data-id="${recommended.id}">Take a look <span>→</span></button></div></div>` : ''}<div class="panel"><div class="panel-header"><div><h3 class="panel-title">Your job search</h3><p class="panel-subtitle">A little momentum goes a long way.</p></div></div><div class="panel-body"><div class="quick-list"><button class="quick-link" data-action="tab" data-tab="My applications"><span class="quick-icon">▤</span>Track your applications<span>→</span></button><button class="quick-link" data-action="tab" data-tab="Saved jobs"><span class="quick-icon">☆</span>Revisit saved roles<span>→</span></button><button class="quick-link" data-action="job-alert"><span class="quick-icon">♧</span>Create a job alert<span>＋</span></button></div></div></div></div></div>`;
}

function jobCard(job, applied = false) {
  const saved = state.savedJobIds.includes(job.id);
  return `<article class="job-card"><div class="job-card-top">${logo(job)}<div class="job-headline"><h3>${escapeHtml(job.title)}</h3><div class="company-name">${escapeHtml(job.company)} <span>·</span> ${escapeHtml(job.category)}</div></div><button class="save-button ${saved ? 'saved' : ''}" data-action="save-job" data-id="${job.id}" aria-label="${saved ? 'Remove saved job' : 'Save job'}">${saved ? '★' : '☆'}</button></div><div class="job-meta"><span>⌖ ${escapeHtml(job.location)}</span><span>◷ ${escapeHtml(job.type)}</span><span>⌂ ${escapeHtml(job.workMode)}</span></div><p class="job-description">${escapeHtml(job.description)}</p><div class="job-tags">${job.tags.map(tag => `<span class="tag">${escapeHtml(tag)}</span>`).join('')}<span class="tag tag-green">${escapeHtml(job.workMode)}</span></div><div class="job-card-footer"><span class="salary">${escapeHtml(job.salary)}</span><span class="posted">${escapeHtml(job.posted)}</span></div><div style="display:flex;justify-content:flex-end;margin-top:10px"><button class="btn ${applied ? 'btn-secondary' : 'btn-primary'} btn-small" data-action="${applied ? 'view-job' : 'apply'}" data-id="${job.id}">${applied ? 'Application sent ✓' : 'View & apply'}</button></div></article>`;
}

function seekerApplicationsPage() {
  const myApps = state.applications.filter(app => app.seekerId === currentUser().id).sort((a, b) => b.id.localeCompare(a.id));
  return `${pageHeading('YOUR JOURNEY', 'My applications', 'Keep an eye on every opportunity and what happens next.', `<button class="btn btn-primary" data-action="tab" data-tab="Discover jobs"><span class="button-icon">＋</span> Find more roles</button>`)}
  <div class="stat-grid">${statCard('Total applications', myApps.length, 'Every opportunity starts somewhere', '▤', 'blue')}${statCard('In progress', myApps.filter(a => ['review', 'shortlisted', 'interview', 'offer'].includes(a.status)).length, 'Still being considered', '◷', 'amber')}${statCard('Interviews', myApps.filter(a => a.status === 'interview').length, 'Time to show them what you can do', '✦', 'green')}${statCard('Offers', myApps.filter(a => ['offer', 'hired'].includes(a.status)).length, 'Good things are possible', '♡', 'green')}</div>
  <div class="panel"><div class="panel-header"><div><h3 class="panel-title">Application activity</h3><p class="panel-subtitle">Your application status, all in one place.</p></div><select class="select-field" style="width:auto;height:31px" id="application-filter"><option value="all">All statuses</option><option value="review">In review</option><option value="interview">Interview</option><option value="rejected">Closed</option></select></div><div class="table-wrap"><table><thead><tr><th>ROLE</th><th>DATE APPLIED</th><th>STATUS</th><th>NEXT STEP</th><th></th></tr></thead><tbody>${myApps.length ? myApps.map(app => { const job = jobById(app.jobId); if (!job) return ''; return `<tr><td><div class="table-primary">${logo(job, true)}<div><strong>${escapeHtml(job.title)}</strong><div class="table-secondary">${escapeHtml(job.company)} · ${escapeHtml(job.location)}</div></div></div></td><td>${escapeHtml(app.date)}</td><td>${statusPill(app.status)}</td><td>${nextStep(app.status)}</td><td><button class="inline-action" data-action="view-job" data-id="${job.id}">View role</button></td></tr>`; }).join('') : `<tr><td colspan="5">${emptyState('Your next opportunity is out there', 'Browse open roles and send your first application.')}</td></tr>`}</tbody></table></div></div>`;
}

function nextStep(status) { return ({ review: 'The team is reviewing your application.', shortlisted: 'You are on the shortlist. Nice work!', interview: 'The team would like to meet you.', offer: 'An offer is waiting for your review.', hired: 'Congratulations on your new role!', rejected: 'This one wasn’t the right fit. Keep going.', withdrawn: 'You withdrew this application.' })[status] || 'Your application has been received.'; }
function seekerSavedPage() { const jobs = state.savedJobIds.map(jobById).filter(Boolean); return `${pageHeading('BOOKMARKED', 'Saved jobs', 'Keep the interesting ones close while you decide what feels right.', `<button class="btn btn-primary" data-action="tab" data-tab="Discover jobs">Explore open roles <span>→</span></button>`)}<div class="job-toolbar"><h2>Your shortlist</h2><span class="result-count">${jobs.length} saved ${jobs.length === 1 ? 'role' : 'roles'}</span></div>${jobs.length ? `<div class="job-grid">${jobs.map(job => jobCard(job, state.applications.some(a => a.jobId === job.id && a.seekerId === currentUser().id))).join('')}</div>` : emptyState('Nothing saved just yet', 'Tap the star on a job to keep it here for later.')}`; }
function seekerProfilePage() { const user = currentUser(); return `${pageHeading('YOUR STORY', 'My profile', 'Help a great team see what makes you, you.', `<button class="btn btn-primary" data-action="edit-profile"><span class="button-icon">✎</span> Edit profile</button>`)}<div class="two-column"><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Personal details</h3><p class="panel-subtitle">The basics employers see when you apply.</p></div><button class="text-link" data-action="edit-profile">Edit</button></div><div class="panel-body"><div class="applicant-cell"><span class="avatar" style="width:48px;height:48px">${initials(user.name)}</span><div><strong>${escapeHtml(user.name)}</strong><div class="table-secondary">${escapeHtml(user.title)}</div></div></div><div class="skeleton-rule"></div><div class="form-grid"><div><span class="table-secondary">EMAIL ADDRESS</span><p>${escapeHtml(user.email)}</p></div><div><span class="table-secondary">LOCATION</span><p>${escapeHtml(user.location || 'Bengaluru, India')}</p></div><div class="full"><span class="table-secondary">ABOUT</span><p>${escapeHtml(user.about || 'Add a short introduction to help employers get to know you.')}</p></div><div class="full"><span class="table-secondary">SKILLS</span><div class="job-tags">${(user.skills || ['Product design', 'Figma', 'User research']).map(x => `<span class="tag">${escapeHtml(x)}</span>`).join('')}</div></div></div></div></div><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Your documents</h3><p class="panel-subtitle">Keep your application materials handy.</p></div></div><div class="panel-body"><div class="notice-box"><span class="notice-symbol">▤</span><span>${user.resumeName ? `<strong>${escapeHtml(user.resumeName)}</strong> is saved on this device.` : 'Add your resume when you apply for a role. It will be linked to your application in this demo.'}<br><small>PDF or DOCX · Max 5 MB</small></span></div><p class="form-hint" style="margin-top:14px">Your personal information is shown only to employers receiving your application in this demo workspace.</p></div></div></div>`; }

function userMessagesCount() {
  const ids = new Set(state.role === 'seeker' ? state.applications.filter(a => a.seekerId === currentUser().id).map(a => a.id) : employerApplications().map(a => a.id));
  return state.messages.filter(message => ids.has(message.appId) && message.senderId !== currentUser().id).length;
}
function messagesPage(eyebrow, title, subtitle) {
  const apps = (state.role === 'seeker' ? state.applications.filter(a => a.seekerId === currentUser().id) : employerApplications()).filter(app => jobById(app.jobId));
  return `${pageHeading(eyebrow, title, subtitle)}<div class="panel"><div class="panel-header"><div><h3 class="panel-title">Your conversations</h3><p class="panel-subtitle">Messages about your applications and roles.</p></div><span class="result-count">${apps.length} ${apps.length === 1 ? 'conversation' : 'conversations'}</span></div><div class="table-wrap"><table><thead><tr><th>${state.role === 'seeker' ? 'EMPLOYER' : 'CANDIDATE'}</th><th>ROLE</th><th>LAST MESSAGE</th><th>STATUS</th><th></th></tr></thead><tbody>${apps.map(app => { const job = jobById(app.jobId), other = state.role === 'seeker' ? personById(job.employerId) : personById(app.seekerId), messages = state.messages.filter(message => message.appId === app.id), last = messages[messages.length - 1]; return `<tr><td><div class="applicant-cell"><span class="mini-avatar teal">${initials(other.name)}</span><div><strong>${escapeHtml(other.name)}</strong><div class="table-secondary">${escapeHtml(other.title)}</div></div></div></td><td>${escapeHtml(job.title)}</td><td>${last ? escapeHtml(last.body.length > 65 ? last.body.slice(0, 62) + '…' : last.body) : 'Start a conversation'}</td><td>${statusPill(app.status)}</td><td><button class="btn btn-secondary btn-small" data-action="open-conversation" data-id="${app.id}">Open messages</button></td></tr>`; }).join('') || `<tr><td colspan="5">${emptyState('No conversations yet', 'Messages about your applications will appear here.')}</td></tr>`}</tbody></table></div></div>`;
}
function openConversation(appId) {
  const app = appById(appId), job = app && jobById(app.jobId); if (!app || !job) return;
  const other = state.role === 'seeker' ? personById(job.employerId) : personById(app.seekerId);
  const messages = state.messages.filter(message => message.appId === app.id);
  const transcript = messages.length ? messages.map(message => { const mine = message.senderId === currentUser().id; return `<div class="chat-message ${mine ? 'mine' : ''}"><div class="chat-author">${mine ? 'You' : escapeHtml(other.name)} · ${escapeHtml(message.date)}</div><div class="chat-bubble">${escapeHtml(message.body)}</div></div>`; }).join('') : `<div class="empty-state" style="padding:18px">No messages yet. Start a conversation.</div>`;
  openModal(`Conversation with ${escapeHtml(other.name)}`, `${escapeHtml(job.title)} · ${statusPill(app.status)}`, `<div class="chat-list">${transcript}</div><form id="message-form"><input type="hidden" name="appId" value="${escapeHtml(app.id)}"><div class="form-field"><label for="message-body">Write a message</label><textarea class="textarea" id="message-body" name="body" placeholder="Keep it kind, clear, and related to the opportunity." required></textarea></div></form>`, `<button class="btn btn-secondary" data-action="close-modal">Close</button><button class="btn btn-primary" data-action="send-message">Send message</button>`, true);
}

function employerJobs() { return state.jobs.filter(job => job.employerId === currentUser().id); }
function employerApplications() { const ids = new Set(employerJobs().map(job => job.id)); return state.applications.filter(app => ids.has(app.jobId)); }
function renderEmployer() { if (state.tab === 'Jobs & applicants') return employerManagePage(); if (state.tab === 'Messages') return messagesPage('CANDIDATE COMMUNICATION', 'Messages', 'Keep candidates informed and make the process feel human.'); if (state.tab === 'Insights') return employerInsightsPage(); if (state.tab === 'Company profile') return employerProfilePage(); return employerOverviewPage(); }

function employerOverviewPage() {
  const jobs = employerJobs(), apps = employerApplications(), pending = jobs.filter(j => j.status === 'pending').length;
  const actions = `<button class="btn btn-secondary" data-action="tab" data-tab="Jobs & applicants">Manage roles</button><button class="btn btn-primary" data-action="post-job"><span class="button-icon">＋</span> Post a job</button>`;
  return `${pageHeading('EMPLOYER WORKSPACE', `Welcome back, ${escapeHtml(currentUser().name.split(' ')[0])}`, 'Here’s what’s happening with your hiring this week.', actions)}
  <div class="stat-grid">${statCard('Active job listings', jobs.filter(j => j.status === 'approved').length, `${pending} awaiting admin review`, '▣', 'green')}${statCard('Applications received', apps.length, '<span class="positive">↑ 12%</span> compared with last month', '↗', 'blue')}${statCard('Needs your review', apps.filter(a => a.status === 'review').length, 'A timely reply makes a difference', '◷', 'amber')}${statCard('Interviewing', apps.filter(a => a.status === 'interview').length, 'Candidates in conversation', '✦', 'green')}</div>
  <div class="two-column"><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Your open roles</h3><p class="panel-subtitle">A quick look at the roles you’re hiring for.</p></div><button class="text-link" data-action="tab" data-tab="Jobs & applicants">View all →</button></div><div class="table-wrap"><table><thead><tr><th>JOB TITLE</th><th>APPLICANTS</th><th>STATUS</th><th></th></tr></thead><tbody>${jobs.slice(0, 5).map(job => `<tr><td><div class="table-primary">${logo(job, true)}<div><strong>${escapeHtml(job.title)}</strong><div class="table-secondary">${escapeHtml(job.location)}</div></div></div></td><td>${job.applicants || 0}</td><td>${statusPill(job.status)}</td><td><button class="inline-action" data-action="edit-job" data-id="${job.id}">Edit</button></td></tr>`).join('') || `<tr><td colspan="4">${emptyState('Your next great hire starts here', 'Post a role and let the right people find you.')}</td></tr>`}</tbody></table></div></div><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Recent activity</h3><p class="panel-subtitle">The latest from your hiring team.</p></div><button class="text-link" data-action="tab" data-tab="Insights">See insights</button></div><div class="panel-body"><div class="activity-list">${state.activity.slice(0, 4).map(activityItem).join('')}</div></div></div></div>
  <div class="two-column section-gap"><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Applicants to review</h3><p class="panel-subtitle">A thoughtful response goes a long way.</p></div><button class="text-link" data-action="tab" data-tab="Jobs & applicants">See applicants →</button></div><div class="table-wrap"><table><thead><tr><th>CANDIDATE</th><th>ROLE</th><th>APPLIED</th><th>STATUS</th><th></th></tr></thead><tbody>${apps.filter(a => a.status === 'review').slice(0, 4).map(applicantRow).join('') || `<tr><td colspan="5"><div class="empty-state" style="padding:20px">All caught up. Your applicants are in good shape.</div></td></tr>`}</tbody></table></div></div><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Hiring snapshot</h3><p class="panel-subtitle">Applications by role this month.</p></div></div><div class="panel-body"><div class="insight-bars">${jobs.filter(j => j.status === 'approved').slice(0, 4).map(job => `<div class="bar-row"><span>${escapeHtml(job.title.length > 15 ? job.title.slice(0, 13) + '…' : job.title)}</span><div class="bar-track"><span style="width:${Math.min(100, Math.max(9, (job.applicants || 1) * 4))}%"></span></div><b>${job.applicants || 0}</b></div>`).join('') || '<span class="form-hint">Post a role to see hiring activity.</span>'}</div></div></div></div>`;
}

function employerManagePage() {
  const jobs = employerJobs(), apps = employerApplications();
  return `${pageHeading('HIRING MANAGER', 'Jobs & applicants', 'Keep roles current and give each candidate a thoughtful next step.', `<button class="btn btn-primary" data-action="post-job"><span class="button-icon">＋</span> Post a job</button>`)}
  ${tabStrip(['My jobs', 'Applicants'], state.manageTab || 'My jobs', 'manage-tab')}
  ${(state.manageTab || 'My jobs') === 'Applicants' ? `<div class="panel"><div class="panel-header"><div><h3 class="panel-title">All applicants</h3><p class="panel-subtitle">${apps.length} candidate applications across your roles</p></div><div class="filter-row"><select class="select-field" id="applicant-status-filter"><option value="all">All statuses</option>${['review', 'shortlisted', 'interview', 'rejected', 'offer', 'hired'].map(s => `<option value="${s}" ${applicantFilter === s ? 'selected' : ''}>${({ review: 'In review', shortlisted: 'Shortlisted', interview: 'Interview', rejected: 'Rejected', offer: 'Offer', hired: 'Hired' })[s]}</option>`).join('')}</select></div></div><div class="table-wrap"><table><thead><tr><th>CANDIDATE</th><th>ROLE</th><th>APPLIED</th><th>STATUS</th><th>UPDATE STATUS</th></tr></thead><tbody>${apps.filter(a => applicantFilter === 'all' || a.status === applicantFilter).map(applicantRow).join('') || `<tr><td colspan="5">${emptyState('No applicants in this view', 'Try another status filter or share your open roles.')}</td></tr>`}</tbody></table></div></div>` : `<div class="panel"><div class="panel-header"><div><h3 class="panel-title">Your job listings</h3><p class="panel-subtitle">Edit details, check approval status, and review applicants.</p></div><span class="result-count">${jobs.length} total roles</span></div><div class="table-wrap"><table><thead><tr><th>ROLE</th><th>POSTED</th><th>APPLICANTS</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${jobs.map(job => `<tr><td><div class="table-primary">${logo(job, true)}<div><strong>${escapeHtml(job.title)}</strong><div class="table-secondary">${escapeHtml(job.location)} · ${escapeHtml(job.workMode)}</div></div></div></td><td>${escapeHtml(job.posted)}</td><td>${job.applicants || 0}</td><td>${statusPill(job.status)}</td><td><div class="row-actions"><button class="inline-action" data-action="edit-job" data-id="${job.id}">Edit</button>${job.status === 'approved' ? `<button class="inline-action" data-action="close-job" data-id="${job.id}">Close</button>` : ''}<button class="inline-action danger" data-action="delete-job" data-id="${job.id}">Delete</button></div></td></tr>`).join('') || `<tr><td colspan="5">${emptyState('No roles posted yet', 'Your next great hire starts with a clear job post.')}</td></tr>`}</tbody></table></div></div>`}`;
}

function applicantRow(app) {
  const person = personById(app.seekerId), job = jobById(app.jobId);
  if (!job) return '';
  const color = ['teal', 'gold', 'blue', 'rose'][Math.abs(person.name.charCodeAt(0)) % 4];
  return `<tr><td><div class="applicant-cell"><span class="mini-avatar ${color}">${initials(person.name)}</span><div><strong>${escapeHtml(person.name)}</strong><div class="table-secondary">${escapeHtml(person.title)}</div></div></div></td><td>${escapeHtml(job.title)}</td><td>${escapeHtml(app.date)}</td><td>${statusPill(app.status)}</td><td><div class="row-actions"><select class="select-field status-select" data-application-id="${app.id}" aria-label="Update ${escapeHtml(person.name)} status"><option value="review" ${app.status === 'review' ? 'selected' : ''}>In review</option><option value="shortlisted" ${app.status === 'shortlisted' ? 'selected' : ''}>Shortlist</option><option value="interview" ${app.status === 'interview' ? 'selected' : ''}>Interview</option><option value="offer" ${app.status === 'offer' ? 'selected' : ''}>Offer</option><option value="hired" ${app.status === 'hired' ? 'selected' : ''}>Hired</option><option value="rejected" ${app.status === 'rejected' ? 'selected' : ''}>Reject</option></select><button class="inline-action" data-action="open-conversation" data-id="${app.id}">Message</button></div></td></tr>`;
}

function employerInsightsPage() {
  const apps = employerApplications(), jobs = employerJobs();
  return `${pageHeading('HIRING ANALYTICS', 'A clearer view of your hiring', 'Small signals that help you make better decisions for your team.')}
  <div class="stat-grid">${statCard('Total applicants', apps.length, 'Across all your roles', '↗', 'blue')}${statCard('Average applicants per role', jobs.length ? Math.round(apps.length / jobs.length) : 0, 'Keep your listings specific and welcoming', '▣', 'green')}${statCard('Interview rate', apps.length ? `${Math.round(apps.filter(a => a.status === 'interview').length / apps.length * 100)}%` : '0%', 'Applicants moved to interview', '◷', 'amber')}${statCard('Open roles', jobs.filter(j => j.status === 'approved').length, 'Visible to job seekers today', '◉', 'green')}</div><div class="two-column"><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Applicants by role</h3><p class="panel-subtitle">A snapshot of interest in your open listings.</p></div></div><div class="panel-body"><div class="insight-bars">${jobs.map(job => `<div class="bar-row"><span>${escapeHtml(job.title.length > 20 ? job.title.slice(0, 18) + '…' : job.title)}</span><div class="bar-track"><span style="width:${Math.min(100, Math.max(6, (job.applicants || 0) * 3))}%"></span></div><b>${job.applicants || 0}</b></div>`).join('')}</div></div></div><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Candidate pipeline</h3><p class="panel-subtitle">Where candidates are in the process.</p></div></div><div class="panel-body"><div class="quick-list">${['review', 'shortlisted', 'interview', 'offer', 'hired'].map(s => `<div class="quick-link"><span class="quick-icon">${({ review: '◷', shortlisted: '☆', interview: '✦', offer: '♡', hired: '✓' })[s]}</span>${({ review: 'In review', shortlisted: 'Shortlisted', interview: 'Interview', offer: 'Offer', hired: 'Hired' })[s]}<span>${apps.filter(a => a.status === s).length}</span></div>`).join('')}</div></div></div></div>`;
}
function employerProfilePage() { const user = currentUser(), company = state.company; return `${pageHeading('YOUR TEAM', 'Company profile', 'Help candidates understand what it feels like to work with you.', `<button class="btn btn-primary" data-action="edit-company"><span class="button-icon">✎</span> Edit profile</button>`)}<div class="panel"><div class="panel-header">${logo({ initials: company.name[0], color: '#e4f0ed', logoColor: '#27816c' })}<div style="flex:1"><h3 class="panel-title">${escapeHtml(company.name)}</h3><p class="panel-subtitle">${escapeHtml(company.industry)} · ${escapeHtml(company.location)} · ${escapeHtml(company.size)}</p></div><span class="tag tag-green">Verified employer</span></div><div class="panel-body"><h3 class="section-heading" style="margin-top:0">A little about us</h3><p class="job-description" style="display:block;max-width:700px">${escapeHtml(company.about)}</p><div class="skeleton-rule"></div><span class="table-secondary">HIRING CONTACT</span><p><strong>${escapeHtml(user.name)}</strong> · ${escapeHtml(user.email)}</p></div></div>`; }

function renderAdmin() { if (state.tab === 'Job approvals') return adminJobsPage(); if (state.tab === 'User management') return adminUsersPage(); if (state.tab === 'System settings') return adminSettingsPage(); if (state.tab === 'Activity log') return adminActivityPage(); return adminOverviewPage(); }
function adminOverviewPage() {
  const pending = state.jobs.filter(j => j.status === 'pending'), activeUsers = state.users.filter(u => u.active).length;
  return `${pageHeading('PLATFORM ADMIN', 'Good morning, Morgan', 'A healthy marketplace starts with a thoughtful review.', `<button class="btn btn-secondary" data-action="tab" data-tab="Activity log"><span class="button-icon">◷</span> Activity log</button>`)}<div class="stat-grid">${statCard('Registered users', activeUsers, '<span class="positive">↑ 8.4%</span> this month', '♙', 'blue')}${statCard('Live job listings', state.jobs.filter(j => j.status === 'approved').length, 'Across all employers', '▣', 'green')}${statCard('Awaiting approval', pending.length, pending.length ? 'These listings need a quick look' : 'All listings are up to date', '◷', 'amber')}${statCard('Applications', state.applications.length, '<span class="positive">↑ 14%</span> this month', '↗', 'green')}</div>
  ${pending.length ? `<div class="admin-callout"><span>✦</span><span><strong>${pending.length} job listing${pending.length === 1 ? '' : 's'} need your review.</strong> A quick approval helps seekers find the right opportunity.</span><button class="text-link" style="margin-left:auto" data-action="tab" data-tab="Job approvals">Review now →</button></div>` : ''}<div class="two-column"><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Listings awaiting review</h3><p class="panel-subtitle">Check that each opportunity is clear and complete.</p></div><button class="text-link" data-action="tab" data-tab="Job approvals">View all →</button></div><div class="table-wrap"><table><thead><tr><th>JOB LISTING</th><th>EMPLOYER</th><th>SUBMITTED</th><th></th></tr></thead><tbody>${pending.slice(0, 4).map(job => `<tr><td><div class="table-primary">${logo(job, true)}<div><strong>${escapeHtml(job.title)}</strong><div class="table-secondary">${escapeHtml(job.location)}</div></div></div></td><td>${escapeHtml(personById(job.employerId).name)}</td><td>${escapeHtml(job.posted)}</td><td><button class="inline-action" data-action="tab" data-tab="Job approvals">Review</button></td></tr>`).join('') || `<tr><td colspan="4"><div class="empty-state" style="padding:22px">Everything is up to date. No listings need review.</div></td></tr>`}</tbody></table></div></div><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Platform activity</h3><p class="panel-subtitle">Recent events across TalentBridge.</p></div><button class="text-link" data-action="tab" data-tab="Activity log">All activity →</button></div><div class="panel-body"><div class="activity-list">${state.activity.slice(0, 5).map(activityItem).join('')}</div></div></div></div><div class="two-column section-gap"><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Job seeker engagement</h3><p class="panel-subtitle">Application activity across the marketplace.</p></div></div><div class="panel-body"><div class="insight-bars">${[['Applications submitted', state.applications.length, 84], ['Jobs saved', state.savedJobIds.length + 23, 62], ['Interviews scheduled', state.applications.filter(a => a.status === 'interview').length + 3, 35], ['Offers shared', state.applications.filter(a => a.status === 'offer').length + 1, 17]].map(([label, count, width]) => `<div class="bar-row"><span>${label}</span><div class="bar-track"><span style="width:${width}%"></span></div><b>${count}</b></div>`).join('')}</div></div></div><div class="panel"><div class="panel-header"><div><h3 class="panel-title">User snapshot</h3><p class="panel-subtitle">Who’s making the marketplace.</p></div><button class="text-link" data-action="tab" data-tab="User management">Manage users →</button></div><div class="panel-body"><div class="quick-list"><div class="quick-link"><span class="quick-icon">♙</span>Job seekers<span>${state.users.filter(u => u.role === 'seeker').length}</span></div><div class="quick-link"><span class="quick-icon">▣</span>Employers<span>${state.users.filter(u => u.role === 'employer').length}</span></div><div class="quick-link"><span class="quick-icon">◉</span>Administrators<span>${state.users.filter(u => u.role === 'admin').length}</span></div></div></div></div></div>`;
}
function adminJobsPage() { const jobs = state.jobs.filter(j => j.status === 'pending' || j.status === 'rejected'); const filter = state.adminJobFilter || 'pending'; return `${pageHeading('CONTENT MODERATION', 'Job approvals', 'Review employer listings before they appear in search.', `<span class="tag tag-amber">${jobs.filter(j => j.status === 'pending').length} awaiting review</span>`)}<div class="panel"><div class="panel-header"><div><h3 class="panel-title">Needs attention</h3><p class="panel-subtitle">Approve clear, complete roles or send them back with a note.</p></div><select class="select-field" id="admin-job-filter" style="width:auto"><option value="pending" ${filter === 'pending' ? 'selected' : ''}>Pending review</option><option value="all" ${filter === 'all' ? 'selected' : ''}>All listings</option><option value="rejected" ${filter === 'rejected' ? 'selected' : ''}>Needs changes</option></select></div><div class="table-wrap"><table><thead><tr><th>JOB LISTING</th><th>EMPLOYER</th><th>SUBMITTED</th><th>STATUS</th><th>DECISION</th></tr></thead><tbody>${jobs.filter(j => filter === 'all' || j.status === filter).map(job => `<tr><td><div class="table-primary">${logo(job, true)}<div><strong>${escapeHtml(job.title)}</strong><div class="table-secondary">${escapeHtml(job.category)} · ${escapeHtml(job.location)}</div></div></div></td><td>${escapeHtml(personById(job.employerId).name)}<div class="table-secondary">${escapeHtml(personById(job.employerId).email)}</div></td><td>${escapeHtml(job.posted)}</td><td>${statusPill(job.status)}</td><td>${job.status === 'pending' ? `<div class="row-actions"><button class="btn btn-primary btn-small" data-action="approve-job" data-id="${job.id}">Approve</button><button class="btn btn-secondary btn-small" data-action="reject-job" data-id="${job.id}">Request changes</button></div>` : `<button class="inline-action" data-action="approve-job" data-id="${job.id}">Reconsider</button>`}</td></tr>`).join('') || `<tr><td colspan="5">${emptyState('No listings need attention', 'New employer submissions will appear here.')}</td></tr>`}</tbody></table></div></div>`; }
function adminUsersPage() { const users = state.users.filter(u => u.role !== 'admin'); return `${pageHeading('PEOPLE & ACCESS', 'User management', 'Keep accounts and roles in good shape.', `<span class="tag">${users.length} members</span>`)}<div class="search-panel" style="margin-bottom:14px"><div class="field-wrap"><span class="field-icon">⌕</span><input class="field" id="user-search" placeholder="Search by name or email" /></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>MEMBER</th><th>ROLE</th><th>JOINED</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody id="user-table-body">${users.map(userRow).join('')}</tbody></table></div></div>`; }
function userRow(user) { return `<tr data-user-row data-search="${escapeHtml((user.name + ' ' + user.email).toLowerCase())}"><td><div class="applicant-cell"><span class="mini-avatar teal">${initials(user.name)}</span><div><strong>${escapeHtml(user.name)}</strong><div class="table-secondary">${escapeHtml(user.email)}</div></div></div></td><td>${fmtRole(user.role)}<div class="table-secondary">${escapeHtml(user.title)}</div></td><td>${escapeHtml(user.joined || 'Oct 2026')}</td><td><span class="status-pill ${user.active ? 'approved' : 'closed'}">${user.active ? 'Active' : 'Paused'}</span></td><td><div class="row-actions"><button class="inline-action" data-action="edit-user" data-id="${user.id}">Edit</button><button class="inline-action" data-action="toggle-user" data-id="${user.id}">${user.active ? 'Pause' : 'Restore'}</button><button class="inline-action danger" data-action="delete-user" data-id="${user.id}">Delete</button></div></td></tr>`; }
function adminSettingsPage() { const entries = [['emailAlerts', 'Platform email notifications', 'Send account and application updates to members.'], ['autoArchive', 'Automatically close old listings', 'Archive roles after their listed closing date.'], ['profileVisibility', 'Allow public employer profiles', 'Make verified company profiles discoverable to job seekers.']]; return `${pageHeading('PLATFORM PREFERENCES', 'System settings', 'Manage the defaults that shape the TalentBridge experience.')}
  <div class="two-column"><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Platform configuration</h3><p class="panel-subtitle">Changes apply across the demo workspace.</p></div></div><div class="panel-body"><div class="settings-list">${entries.map(([key, title, description]) => `<div class="setting-row"><div><strong>${title}</strong><p>${description}</p></div><button class="toggle ${state.settings[key] ? 'on' : ''}" data-action="toggle-setting" data-key="${key}" aria-label="Toggle ${title}" aria-pressed="${state.settings[key]}"></button></div>`).join('')}</div></div></div><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Platform defaults</h3><p class="panel-subtitle">A few guardrails for a welcoming marketplace.</p></div></div><div class="panel-body"><div class="form-field"><label for="default-review">Default job review window</label><select class="select-field" id="default-review"><option>Within 2 business days</option><option>Within 3 business days</option><option>Within 5 business days</option></select></div><div class="form-field" style="margin-top:14px"><label for="file-limit">Resume upload size limit</label><select class="select-field" id="file-limit"><option>5 MB</option><option>10 MB</option></select></div><div class="notice-box" style="margin-top:15px"><span class="notice-symbol">ⓘ</span><span>These settings are saved locally for this prototype. A production platform should store these in a protected server-side configuration.</span></div></div></div></div>`; }
function adminActivityPage() { return `${pageHeading('AUDIT TRAIL', 'Activity log', 'A running record of important actions across your workspace.')}
  <div class="panel"><div class="panel-header"><div><h3 class="panel-title">Recent activity</h3><p class="panel-subtitle">${state.activity.length} recent events</p></div><button class="btn btn-secondary btn-small" data-action="clear-activity">Clear demo log</button></div><div class="panel-body"><div class="activity-list">${state.activity.map(activityItem).join('') || '<div class="empty-state">No recent activity.</div>'}</div></div></div>`; }
function activityItem(item) { return `<div class="activity-item"><span class="activity-dot">${escapeHtml(item.icon || '•')}</span><div class="activity-copy">${item.text}<div class="activity-time">${escapeHtml(item.time)}</div></div></div>`; }
function emptyState(title, description) { return `<div class="empty-state"><div class="empty-icon">✦</div><strong>${title}</strong><p>${description}</p></div>`; }

function openModal(title, subtitle, content, footer, wide = false) {
  const backdrop = document.getElementById('modal-backdrop');
  backdrop.innerHTML = `<div class="modal ${wide ? 'wide' : ''}" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><div class="modal-header"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><div class="modal-content">${content}</div>${footer ? `<div class="modal-footer">${footer}</div>` : ''}</div>`;
  backdrop.hidden = false;
  const first = backdrop.querySelector('input, select, textarea, button'); if (first) first.focus();
}
function closeModal() { const backdrop = document.getElementById('modal-backdrop'); backdrop.hidden = true; backdrop.innerHTML = ''; }
function showProfileModal() { const user = currentUser(); openModal('Your profile', 'Keep your details up to date so the right people can reach you.', `<form id="profile-form"><div class="form-grid"><div class="form-field"><label for="profile-name">Full name</label><input class="field" id="profile-name" name="name" value="${escapeHtml(user.name)}" required /></div><div class="form-field"><label for="profile-title">Headline</label><input class="field" id="profile-title" name="title" value="${escapeHtml(user.title)}" required /></div><div class="form-field"><label for="profile-email">Email</label><input class="field" id="profile-email" name="email" type="email" value="${escapeHtml(user.email)}" required /></div><div class="form-field"><label for="profile-location">Location</label><input class="field" id="profile-location" name="location" value="${escapeHtml(user.location || 'Bengaluru, India')}" /></div><div class="form-field full"><label for="profile-about">A little about you</label><textarea class="textarea" id="profile-about" name="about" placeholder="What kind of work do you love doing?">${escapeHtml(user.about || '')}</textarea></div><div class="form-field full"><label for="profile-skills">Skills <span class="form-hint">· separated by commas</span></label><input class="field" id="profile-skills" name="skills" value="${escapeHtml((user.skills || ['Product design', 'Figma', 'User research']).join(', '))}" /></div></div></form>`, `<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-profile">Save profile</button>`); }
function showCompanyModal() { const company = state.company; openModal('Edit company profile', 'Give candidates a clear picture of your team.', `<form id="company-form"><div class="form-grid"><div class="form-field full"><label for="company-name">Company name</label><input class="field" id="company-name" name="name" value="${escapeHtml(company.name)}" required /></div><div class="form-field"><label for="company-industry">Industry</label><input class="field" id="company-industry" name="industry" value="${escapeHtml(company.industry)}" /></div><div class="form-field"><label for="company-size">Team size</label><select class="select-field" id="company-size" name="size">${['1–10 employees', '11–50 employees', '51–200 employees', '201–500 employees', '500+ employees'].map(x => `<option ${company.size === x ? 'selected' : ''}>${x}</option>`).join('')}</select></div><div class="form-field full"><label for="company-location">Location</label><input class="field" id="company-location" name="location" value="${escapeHtml(company.location)}" /></div><div class="form-field full"><label for="company-about">About your team</label><textarea class="textarea" id="company-about" name="about" required>${escapeHtml(company.about)}</textarea></div></div></form>`, `<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-company">Save company profile</button>`); }
function showUserModal(userId) { const user = state.users.find(entry => entry.id === userId); if (!user) return; openModal('Edit member', 'Update the account details and role for this member.', `<form id="user-form"><input type="hidden" name="id" value="${escapeHtml(user.id)}"><div class="form-grid"><div class="form-field"><label for="member-name">Full name</label><input class="field" id="member-name" name="name" value="${escapeHtml(user.name)}" required></div><div class="form-field"><label for="member-title">Headline</label><input class="field" id="member-title" name="title" value="${escapeHtml(user.title)}" required></div><div class="form-field full"><label for="member-email">Email address</label><input class="field" id="member-email" name="email" type="email" value="${escapeHtml(user.email)}" required></div><div class="form-field"><label for="member-role">Account role</label><select class="select-field" id="member-role" name="role">${['seeker', 'employer', 'admin'].map(role => `<option value="${role}" ${user.role === role ? 'selected' : ''}>${fmtRole(role)}</option>`).join('')}</select></div></div></form>`, `<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-user">Save changes</button>`); }
function showJobModal(existing = null) { const job = existing || {}; openModal(existing ? 'Edit job listing' : 'Post a new job', existing ? 'Make changes to your listing. Editing sends it back for approval.' : 'Share a clear, welcoming description of your opportunity.', `<form id="job-form"><input type="hidden" name="id" value="${escapeHtml(job.id || '')}"/><div class="form-grid"><div class="form-field full"><label for="job-title">Job title *</label><input class="field" id="job-title" name="title" placeholder="e.g. Senior Product Designer" value="${escapeHtml(job.title || '')}" required /></div><div class="form-field"><label for="job-category">Category *</label><select class="select-field" id="job-category" name="category" required><option value="">Choose a category</option>${['Design', 'Engineering', 'Marketing', 'People', 'Customer Success', 'Operations', 'Finance'].map(x => `<option ${job.category === x ? 'selected' : ''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="job-type">Employment type</label><select class="select-field" id="job-type" name="type">${['Full-time', 'Part-time', 'Contract', 'Internship'].map(x => `<option ${job.type === x ? 'selected' : ''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="job-location">Location *</label><input class="field" id="job-location" name="location" placeholder="City, country or Remote" value="${escapeHtml(job.location || '')}" required /></div><div class="form-field"><label for="job-mode">Work style</label><select class="select-field" id="job-mode" name="workMode">${['Hybrid', 'Remote', 'On-site'].map(x => `<option ${job.workMode === x ? 'selected' : ''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="job-salary">Salary range</label><input class="field" id="job-salary" name="salary" placeholder="e.g. ₹18–24 LPA" value="${escapeHtml(job.salary || '')}" /></div><div class="form-field"><label for="job-tags">Skills / requirements</label><input class="field" id="job-tags" name="tags" placeholder="Figma, Research, 3+ years" value="${escapeHtml((job.tags || []).join(', '))}" /></div><div class="form-field full"><label for="job-description">About the role *</label><textarea class="textarea" id="job-description" name="description" required placeholder="Describe the work, the team, and who might enjoy this role.">${escapeHtml(job.description || '')}</textarea><span class="form-hint">New and edited listings are reviewed by an administrator before going live.</span></div></div></form>`, `<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-job-form">${existing ? 'Send for review' : 'Submit for review'}</button>`, true); }
function showApplyModal(job) { const already = state.applications.some(app => app.seekerId === currentUser().id && app.jobId === job.id); if (already) { openModal('You’ve already applied', 'Your application is saved in your application tracker.', `<div class="notice-box"><span class="notice-symbol">✓</span><span>You applied for <strong>${escapeHtml(job.title)}</strong> at ${escapeHtml(job.company)}. You can follow updates in My applications.</span></div>`, `<button class="btn btn-secondary" data-action="close-modal">Close</button><button class="btn btn-primary" data-action="tab" data-tab="My applications">Track application</button>`); return; }
  openModal(`Apply to ${escapeHtml(job.company)}`, escapeHtml(job.title), `<form id="application-form"><div class="form-field"><label for="cover-letter">A note to the hiring team</label><textarea class="textarea" id="cover-letter" name="note" placeholder="What interests you about this role? A short introduction goes a long way."></textarea></div><div class="form-field" style="margin-top:14px"><label for="resume-file">Resume</label><div class="upload-box"><input type="file" id="resume-file" name="resume" accept=".pdf,.doc,.docx" /><small>PDF or DOCX, up to 5 MB. This demo saves the file name only; no file is uploaded.</small></div></div><p class="form-hint" style="margin-top:13px">By applying, you agree to share your profile details and application materials with ${escapeHtml(job.company)}.</p></form>`, `<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="submit-application">Send application</button>`); }
function showJobDetail(job) { const applied = state.applications.some(a => a.jobId === job.id && a.seekerId === currentUser().id); openModal(escapeHtml(job.title), `${escapeHtml(job.company)} · ${escapeHtml(job.location)}`, `<div class="job-meta"><span>◷ ${escapeHtml(job.type)}</span><span>⌂ ${escapeHtml(job.workMode)}</span><span>${escapeHtml(job.salary)}</span></div><h3 class="section-heading" style="margin-top:18px">About this opportunity</h3><p class="job-description" style="display:block;line-height:1.8">${escapeHtml(job.description)}</p><div class="job-tags">${job.tags.map(x => `<span class="tag">${escapeHtml(x)}</span>`).join('')}</div><div class="notice-box" style="margin-top:18px"><span class="notice-symbol">✦</span><span>Posted ${escapeHtml(job.posted)} · ${job.applicants || 0} people have applied</span></div>`, `<button class="btn btn-secondary" data-action="save-job" data-id="${job.id}">${state.savedJobIds.includes(job.id) ? '★ Saved' : '☆ Save'}</button>${state.role === 'seeker' ? `<button class="btn btn-primary" data-action="${applied ? 'tab' : 'apply'}" data-tab="My applications" data-id="${job.id}">${applied ? 'View application' : 'Apply for this role'}</button>` : ''}`); }

function handleAction(button) {
  const action = button.dataset.action, id = button.dataset.id;
  if (action === 'menu') { document.getElementById('sidebar').classList.toggle('open'); document.querySelector('.mobile-overlay').classList.toggle('show'); }
  if (action === 'home') { state.role = 'seeker'; state.tab = 'Discover jobs'; render(); }
  if (action === 'tab') { state.tab = button.dataset.tab; state.manageTab = state.tab === 'Jobs & applicants' ? (state.manageTab || 'My jobs') : state.manageTab; if (state.tab === 'My applications') applicantFilter = 'all'; render(); closeModal(); document.getElementById('sidebar').classList.remove('open'); document.querySelector('.mobile-overlay')?.classList.remove('show'); }
  if (action === 'manage-tab') { state.manageTab = button.dataset.tab; render(); }
  if (action === 'profile') showProfileModal();
  if (action === 'edit-profile') showProfileModal();
  if (action === 'edit-company') showCompanyModal();
  if (action === 'edit-user') showUserModal(id);
  if (action === 'post-job') showJobModal();
  if (action === 'edit-job') { const job = jobById(id); if (job) showJobModal(job); }
  if (action === 'save-job') { if (state.savedJobIds.includes(id)) state.savedJobIds = state.savedJobIds.filter(x => x !== id); else state.savedJobIds.push(id); persist(); render(); if (!document.getElementById('modal-backdrop').hidden) { const job = jobById(id); if (job) showJobDetail(job); } else toast(state.savedJobIds.includes(id) ? 'Saved to your shortlist.' : 'Removed from saved jobs.'); }
  if (action === 'apply') { const job = jobById(id); if (job) showApplyModal(job); }
  if (action === 'view-job') { const job = jobById(id); if (job) showJobDetail(job); }
  if (action === 'open-conversation') openConversation(id);
  if (action === 'close-modal') closeModal();
  if (action === 'save-job' && button.closest('.modal')) closeModal();
  if (action === 'clear-search') { searchFilters = { query: '', location: '', category: '' }; render(); }
  if (action === 'job-alert') { createJobAlert(); }
  if (action === 'create-alert') { createJobAlert(); }
  if (action === 'remove-alert') { state.jobAlerts = state.jobAlerts.filter(alert => alert.id !== id); persist(); showJobAlerts(); toast('Job alert removed.'); }
  if (action === 'manage-alerts') showJobAlerts();
  if (action === 'notifications') openModal('You’re all caught up', 'We’ll let you know when something needs your attention.', `<div class="activity-list">${state.activity.slice(0, 3).map(activityItem).join('')}</div>`, `<button class="btn btn-primary" data-action="close-modal">Sounds good</button>`);
  if (action === 'help') openModal('We’re here to help', 'A few good places to get started.', `<div class="quick-list"><button class="quick-link" data-action="close-modal"><span class="quick-icon">▤</span>Getting started guide<span>↗</span></button><button class="quick-link" data-action="close-modal"><span class="quick-icon">✉</span>Contact support<span>↗</span></button></div>`, `<button class="btn btn-secondary" data-action="close-modal">Close</button>`);
  if (action === 'save-profile') saveProfile();
  if (action === 'save-company') saveCompany();
  if (action === 'save-user') saveUser();
  if (action === 'save-job-form') saveJobForm();
  if (action === 'submit-application') submitApplication();
  if (action === 'send-message') sendMessage();
  if (action === 'approve-job') { const job = jobById(id); if (job) { job.status = 'approved'; job.posted = 'Just now'; setActivity(`Job listing <strong>${escapeHtml(job.title)}</strong> was approved.`, '✓'); persist(); render(); toast('Listing approved and visible to job seekers.'); } }
  if (action === 'reject-job') { const job = jobById(id); if (job) { job.status = 'rejected'; setActivity(`Changes requested for <strong>${escapeHtml(job.title)}</strong>.`, '↺'); persist(); render(); toast('Changes requested. The employer can edit and resubmit.'); } }
  if (action === 'toggle-user') { const user = state.users.find(u => u.id === id); if (user) { user.active = !user.active; setActivity(`Account access for <strong>${escapeHtml(user.name)}</strong> was ${user.active ? 'restored' : 'paused'}.`, '♙'); persist(); render(); toast(user.active ? 'Account access restored.' : 'Account access paused.'); } }
  if (action === 'delete-user') { const user = state.users.find(u => u.id === id); if (user && confirm(`Delete ${user.name}'s account? Their applications and messages will also be removed from this demo.`)) { const jobIds = state.jobs.filter(job => job.employerId === user.id).map(job => job.id); const appIds = state.applications.filter(app => app.seekerId === user.id || jobIds.includes(app.jobId)).map(app => app.id); state.users = state.users.filter(entry => entry.id !== user.id); state.jobs = state.jobs.filter(job => job.employerId !== user.id); state.applications = state.applications.filter(app => !appIds.includes(app.id)); state.messages = state.messages.filter(message => !appIds.includes(message.appId)); setActivity(`Member account for <strong>${escapeHtml(user.name)}</strong> was deleted.`, '−'); persist(); render(); toast('Member account deleted.'); } }
  if (action === 'toggle-setting') { const key = button.dataset.key; state.settings[key] = !state.settings[key]; persist(); render(); toast('Platform setting saved.'); }
  if (action === 'reset-demo') { openModal('Reset demo workspace?', 'This will restore the original sample jobs, accounts, and applications on this browser.', `<div class="notice-box"><span class="notice-symbol">↺</span><span>Your current demo changes will be replaced by the starter data.</span></div>`, `<button class="btn btn-secondary" data-action="close-modal">Keep my changes</button><button class="btn btn-primary" data-action="confirm-reset">Reset workspace</button>`); }
  if (action === 'confirm-reset') { try { window.localStorage.removeItem(STORAGE_KEY); } catch (error) { /* Storage may be disabled; reset the in-memory demo anyway. */ } state = structuredClone(seedData); searchFilters = { query: '', location: '', category: '' }; render(); closeModal(); toast('Demo workspace restored.'); }
  if (action === 'delete-job') { const job = jobById(id); if (job && confirm(`Delete “${job.title}”? This removes the listing from this demo workspace.`)) { state.jobs = state.jobs.filter(j => j.id !== id); state.applications = state.applications.filter(a => a.jobId !== id); setActivity(`Job listing <strong>${escapeHtml(job.title)}</strong> was deleted.`, '−'); persist(); render(); toast('Job listing deleted.'); } }
  if (action === 'close-job') { const job = jobById(id); if (job) { job.status = 'closed'; setActivity(`Job listing <strong>${escapeHtml(job.title)}</strong> was closed.`, '✓'); persist(); render(); toast('Job listing closed.'); } }
  if (action === 'clear-activity') { state.activity = []; persist(); render(); toast('Demo activity log cleared.'); }
}

function saveProfile() {
  const form = document.getElementById('profile-form'); if (!form.reportValidity()) return;
  const data = new FormData(form), user = currentUser();
  user.name = data.get('name').trim(); user.title = data.get('title').trim(); user.email = data.get('email').trim(); user.location = data.get('location').trim(); user.about = data.get('about').trim(); user.skills = data.get('skills').split(',').map(x => x.trim()).filter(Boolean);
  setActivity(`<strong>${escapeHtml(user.name)}</strong> updated their profile.`, '◉'); persist(); closeModal(); render(); toast('Profile updated.');
}
function createJobAlert() {
  const criteria = { query: searchFilters.query, location: searchFilters.location, category: searchFilters.category || 'Design' };
  const exists = state.jobAlerts.some(alert => alert.query === criteria.query && alert.location === criteria.location && alert.category === criteria.category);
  if (!exists) state.jobAlerts.unshift({ id: `alert-${Date.now()}`, ...criteria, created: 'Just now' });
  persist(); showJobAlerts(); if (!exists) toast('Job alert saved on this device.');
}
function showJobAlerts() {
  const alerts = state.jobAlerts;
  const content = alerts.length ? `<div class="quick-list">${alerts.map(alert => `<div class="setting-row"><div><strong>${escapeHtml(alert.query || alert.category || 'All jobs')}</strong><p>${escapeHtml([alert.category, alert.location].filter(Boolean).join(' · ') || 'All locations')} · Saved ${escapeHtml(alert.created || 'recently')}</p></div><button class="inline-action danger" data-action="remove-alert" data-id="${alert.id}">Remove</button></div>`).join('')}</div>` : emptyState('No job alerts yet', 'Save a search and we’ll keep it here for you in this demo.');
  openModal('Your job alerts', 'Saved search criteria on this device.', content, `<button class="btn btn-secondary" data-action="close-modal">Close</button><button class="btn btn-primary" data-action="create-alert">Save current search</button>`);
}
function saveJobForm() {
  const form = document.getElementById('job-form'); if (!form.reportValidity()) return;
  const data = new FormData(form), id = data.get('id'), existing = id && jobById(id);
  const company = state.role === 'employer' ? state.company.name : currentUser().name;
  const job = { ...(existing || {}), id: existing?.id || `j-${Date.now()}`, title: data.get('title').trim(), category: data.get('category'), type: data.get('type'), location: data.get('location').trim(), workMode: data.get('workMode'), salary: data.get('salary').trim() || 'Salary not listed', tags: data.get('tags').split(',').map(x => x.trim()).filter(Boolean), description: data.get('description').trim(), company: existing?.company || company, initials: existing?.initials || company[0], color: existing?.color || '#e4f0ed', logoColor: existing?.logoColor || '#27816c', employerId: currentUser().id, posted: existing ? 'Updated just now' : 'Just now', applicants: existing?.applicants || 0, status: 'pending' };
  if (existing) Object.assign(existing, job); else state.jobs.unshift(job);
  setActivity(`Job listing <strong>${escapeHtml(job.title)}</strong> was submitted for review.`, '+'); persist(); closeModal(); render(); toast(existing ? 'Changes submitted for review.' : 'Job submitted. It will be visible after admin approval.');
}
function saveCompany() {
  const form = document.getElementById('company-form'); if (!form.reportValidity()) return;
  const data = new FormData(form);
  state.company = { name: data.get('name').trim(), industry: data.get('industry').trim(), size: data.get('size'), location: data.get('location').trim(), about: data.get('about').trim() };
  state.jobs.filter(job => job.employerId === currentUser().id).forEach(job => { job.company = state.company.name; job.initials = state.company.name[0]; });
  setActivity(`<strong>${escapeHtml(state.company.name)}</strong> updated its company profile.`, '◉'); persist(); closeModal(); render(); toast('Company profile updated.');
}
function saveUser() {
  const form = document.getElementById('user-form'); if (!form.reportValidity()) return;
  const data = new FormData(form), user = state.users.find(entry => entry.id === data.get('id'));
  if (!user) return;
  const email = data.get('email').trim().toLowerCase();
  if (state.users.some(entry => entry.id !== user.id && entry.email.toLowerCase() === email)) { toast('That email address is already in use.', false); return; }
  user.name = data.get('name').trim(); user.title = data.get('title').trim(); user.email = email; user.role = data.get('role');
  setActivity(`Account details for <strong>${escapeHtml(user.name)}</strong> were updated.`, '♙'); persist(); closeModal(); render(); toast('Member details updated.');
}
function submitApplication() {
  const form = document.getElementById('application-form'); if (!form.reportValidity()) return;
  const jobId = document.querySelector('.modal')?.dataset.jobId;
  // The apply action stores the selected job id on the dialog before submission.
  const job = jobById(jobId || window.currentApplyJobId); if (!job) return;
  const file = document.getElementById('resume-file').files[0];
  if (file && file.size > 5 * 1024 * 1024) { toast('That file is larger than 5 MB. Choose a smaller resume.', false); return; }
  const app = { id: `a-${Date.now()}`, jobId: job.id, seekerId: currentUser().id, status: 'review', date: new Date().toLocaleDateString('en-IN', { month: 'short', day: 'numeric', year: 'numeric' }), note: new FormData(form).get('note').trim(), resumeName: file?.name || '' };
  state.applications.unshift(app); job.applicants = (job.applicants || 0) + 1; if (file) currentUser().resumeName = file.name;
  setActivity(`<strong>${escapeHtml(currentUser().name)}</strong> applied for <strong>${escapeHtml(job.title)}</strong>.`, '↗'); persist(); closeModal(); render(); toast('Application sent. Good luck!');
}
function sendMessage() {
  const form = document.getElementById('message-form'); if (!form.reportValidity()) return;
  const data = new FormData(form), body = data.get('body').trim(), appId = data.get('appId');
  if (!body) return;
  state.messages.push({ id: `m-${Date.now()}`, appId, senderId: currentUser().id, body, date: new Date().toLocaleString('en-IN', { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }) });
  const app = appById(appId), job = app && jobById(app.jobId);
  if (job) setActivity(`<strong>${escapeHtml(currentUser().name)}</strong> sent a message about <strong>${escapeHtml(job.title)}</strong>.`, '✉');
  persist(); closeModal(); render(); toast('Message sent.');
}

document.addEventListener('click', event => {
  const button = event.target.closest('[data-action]'); if (!button) return;
  if (button.dataset.action === 'apply') window.currentApplyJobId = button.dataset.id;
  if (button.dataset.action === 'save-job' && button.closest('.modal')) { const id = button.dataset.id; if (state.savedJobIds.includes(id)) state.savedJobIds = state.savedJobIds.filter(x => x !== id); else state.savedJobIds.push(id); persist(); closeModal(); render(); toast(state.savedJobIds.includes(id) ? 'Saved to your shortlist.' : 'Removed from saved jobs.'); return; }
  handleAction(button);
});
document.addEventListener('change', event => {
  if (event.target.id === 'role-switcher') { state.role = event.target.value; state.tab = ({ seeker: 'Discover jobs', employer: 'Overview', admin: 'Overview' })[state.role]; render(); }
  if (event.target.matches('.status-select')) { const app = appById(event.target.dataset.applicationId); if (app) { app.status = event.target.value; setActivity(`Application status was updated for <strong>${escapeHtml(personById(app.seekerId).name)}</strong>.`, '↗'); persist(); render(); toast('Candidate status updated.'); } }
  if (event.target.id === 'application-filter') { const value = event.target.value; const rows = document.querySelectorAll('.panel tbody tr'); rows.forEach(row => { const pill = row.querySelector('.status-pill'); row.hidden = value !== 'all' && pill && !pill.classList.contains(value); }); }
  if (event.target.id === 'applicant-status-filter') { applicantFilter = event.target.value; render(); }
  if (event.target.id === 'admin-job-filter') { state.adminJobFilter = event.target.value; render(); }
});
document.addEventListener('input', event => {
  if (event.target.id === 'user-search') { const query = event.target.value.toLowerCase(); document.querySelectorAll('[data-user-row]').forEach(row => { row.hidden = !row.dataset.search.includes(query); }); }
});
document.addEventListener('submit', event => {
  if (event.target.id === 'job-search-form') { event.preventDefault(); const data = new FormData(event.target); searchFilters = { query: data.get('query').trim(), location: data.get('location').trim(), category: data.get('category') }; render(); }
  if (event.target.id === 'profile-form') { event.preventDefault(); saveProfile(); }
  if (event.target.id === 'company-form') { event.preventDefault(); saveCompany(); }
  if (event.target.id === 'user-form') { event.preventDefault(); saveUser(); }
  if (event.target.id === 'job-form') { event.preventDefault(); saveJobForm(); }
  if (event.target.id === 'application-form') { event.preventDefault(); submitApplication(); }
  if (event.target.id === 'message-form') { event.preventDefault(); sendMessage(); }
});
document.addEventListener('keydown', event => { if (event.key === 'Escape') closeModal(); });
document.getElementById('modal-backdrop').addEventListener('click', event => { if (event.target.id === 'modal-backdrop') closeModal(); });
document.querySelector('.app-shell').insertAdjacentHTML('beforeend', '<div class="mobile-overlay"></div>');
render();
